/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"production-level-5","number":5,"title":"Module 5 — Session Labs: Hip-Hop and Trap","skillBand":"Textbook","duration":"From the course textbook","summary":"Skip both and go to Module 5 or 7. Pop default remains.","modules":[{"id":"production-m-5-1","code":"5","title":"Hip-hop / boom-bap and trap labs (skippable)","blurb":"Skip both and go to Module 5 or 7. Pop default remains.","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"production-l-o-8","title":"Section overview","blocks":[{"type":"step","title":"overview","blocks":[{"type":"heading","text":"Module 5 — Hip-hop / boom-bap and trap labs (skippable)","level":1},{"type":"prose","html":"Skip both and go to Module 5 or 7. Pop default remains.   <strong>Do not:</strong> Amen-as-DnB-science (Drums). Do not teach 32nd-hat curriculum. Legal sources only (1.6)."},{"type":"heading","text":"Section 5.1 — G-HH · Hip-hop / boom-bap (skippable)","level":1},{"type":"prose","html":"<strong>Topics:</strong> Loop as verse engine; hook as the only “drop.” 16-bar verse / 8-bar hook as a <em>common</em> grid — cite, do not legislate. Phrase chops on 16 pads. Unwarped tap-to-grid as <em>one</em> flip method."}]}],"minutes":8},{"id":"production-l4-1-1","title":"5.1.1 — Verse = loop + new talk; hook = the remembered line","blocks":[{"type":"step","title":"5.1.1 — Verse = loop + new talk; hook = the remembered line","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Verse = loop + new talk; hook = the remembered line.  "},{"type":"prose","html":"Cole Mize (How To Rap: Song Structure): the <strong>verse</strong> is typically longer and <em>sparser</em> so lyrics can be the focus; the <strong>hook</strong> (chorus) is typically the <strong>busiest</strong> section and the remembered line, often repeated 3–4 times."},{"type":"prose","html":"Production: the verse engine is often <strong>one loop</strong> that does not change much while “talk” (a vocal that may not exist yet, or a hummed placeholder) is new each verse. The hook is the clip people would hum."},{"type":"prose","html":"This is not a 140 drop. The hook is the only section that behaves like a “drop” in pop-energy language."},{"type":"prose","html":"<strong>Check:</strong> You can name the loop clip vs the hook clip."}]}],"minutes":8},{"id":"production-l4-1-2","title":"5.1.2 — 16-bar verse / 8-bar hook as a common grid — cite or","blocks":[{"type":"step","title":"5.1.2 — 16-bar verse / 8-bar hook as a common grid — cite or","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Cite or <code>gap</code>.  "},{"type":"prose","html":"<strong>Cited common shape — not a law:</strong>"},{"type":"prose","html":"Cole Mize: hooks typically <strong>8</strong> bars; verses usually <strong>12–16</strong> bars."},{"type":"prose","html":"AudeoBox pictured MPC-classic map (syllabus):   <code>Intro 2–4</code> (sample, light or no drums) → <code>Verse 16</code> (full beat) → <code>Hook 8</code> (variation / filter) → <code>Verse 16</code> → <code>Hook 8</code> → <code>Outro 4–8</code> (elements drop)."},{"type":"prose","html":"If your owned reference song is 12-bar verses or a 16-bar hook, write <strong><code>gap</code></strong> and follow <em>that</em> song. Do not stretch a 12-bar verse to 16 “because the course said.”"},{"type":"prose","html":"<strong>Check:</strong> Your scene lengths are either the cited grid or a written gap."}]}],"minutes":8},{"id":"production-l4-1-3","title":"5.1.3 — Tempo: cite melodigging ~85–96 or leave numbered tempo out","blocks":[{"type":"step","title":"5.1.3 — Tempo: cite melodigging ~85–96 or leave numbered tempo out","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Tempo: cite melodigging ~85–96 or leave numbered tempo out.  "},{"type":"prose","html":"Melodigging (<em>Jazz Boom Bap</em> / boom-bap pages): the style typically runs around <strong>85–96 BPM</strong> (they also write 85–95 with swing). That is a <strong>cited band</strong>, not a required number."},{"type":"prose","html":"If you do not want a number, <strong>tap</strong> and leave the Control Bar as the tap. Do not invent 87 because it “sounds boom-bap.”"},{"type":"prose","html":"Swing (Melodigging: try 54–62% on 16ths) is optional feel — not a drum exam."},{"type":"prose","html":"<strong>Check:</strong> The Set either shows a tempo inside 85–96 with the source named, or has no claimed genre BPM."}]}],"minutes":8},{"id":"production-l4-1-4","title":"5.1.4 — Intro as filtered sample","blocks":[{"type":"step","title":"5.1.4 — Intro as filtered sample","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Intro as filtered sample.  "},{"type":"prose","html":"AudeoBox cousin: 2–4 bars of the sample, drums light or absent, often <strong>filtered</strong>. Auto Filter on the audio clip or a Simpler pad. Opening the filter at the verse downbeat is a section edge (2.4.5 cousin), not sound design class."},{"type":"prose","html":"Legal sample only (4.1.8)."},{"type":"prose","html":"<strong>Check:</strong> <code>Intro</code> is thinner than <code>Verse</code> because of filter and/or missing drums."}]}],"minutes":8},{"id":"production-l4-1-5","title":"5.1.5 — Chop a legal phrase onto pads","blocks":[{"type":"step","title":"5.1.5 — Chop a legal phrase onto pads","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Chop a legal phrase onto pads.  "},{"type":"prose","html":"Reuse 1.4: royalty-free or self-recorded phrase → Slice to Drum Rack → 8–16 pads, notes 36–51, channel 10. This is the MPC cousin on <strong>Live’s</strong> Rack. No Sampler."},{"type":"prose","html":"<strong>Check:</strong> Pad 1 = C1 = 36 still true. Phrase is tagged <code>RF</code> or <code>OWN</code>."}]}],"minutes":8},{"id":"production-l4-1-6","title":"5.1.6 — Flip the order; keep the hook clip shorter","blocks":[{"type":"step","title":"5.1.6 — Flip the order; keep the hook clip shorter","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Flip the order; keep the hook clip shorter.  "},{"type":"prose","html":"Resequence the staircase (1.4.4). The <strong>hook</strong> clip is the shorter, busier row (8 bars on the common grid). The verse can be the same chops in a calmer order, or the un-flipped loop."},{"type":"prose","html":"A flip here is a <strong>method</strong> inside a lab, not Deliverable 4. Identity may already be blurry. Keep the source log."},{"type":"prose","html":"<strong>Check:</strong> Hook scene is shorter than verse scene, unless you wrote a gap."}]}],"minutes":8},{"id":"production-l4-1-7","title":"5.1.7 — Second verse = same loop, one clip changed","blocks":[{"type":"step","title":"5.1.7 — Second verse = same loop, one clip changed","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Second verse = same loop, one clip changed.  "},{"type":"prose","html":"Duplicate <code>Verse</code> → <code>Verse_2</code>. Change <strong>one</strong> clip (a hat, a bass rest, a new chop). The talk would be new; the engine stays. This is how 16+16 bars do not become a new beat."},{"type":"prose","html":"<strong>Check:</strong> Diff of the two verse scenes is one clip."}]}],"minutes":8},{"id":"production-l4-1-8","title":"5.1.8 — Consent / royalty-free reminder","blocks":[{"type":"step","title":"5.1.8 — Consent / royalty-free reminder","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Consent / royalty-free reminder.  "},{"type":"prose","html":"1.6 again, because boom-bap culture is built on records you probably do <strong>not</strong> own. <em>Drum Breaks</em>: consent first; royalty-free is the safe path. Classic-break “everyone uses Amen” is <strong>grey</strong>, not a classroom license."},{"type":"prose","html":"This lab’s chop is <code>OWN</code>, <code>RF</code>, <code>PACK</code>, or <code>PD</code>. No vinyl rip for the sketch you might later export."},{"type":"prose","html":"<strong>Check:</strong> Source-log line exists for the phrase."}]}],"minutes":8},{"id":"production-l4-1-9","title":"5.1.9 — Unwarped tap-to-grid optional path","blocks":[{"type":"step","title":"5.1.9 — Unwarped tap-to-grid optional path","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Unwarped tap-to-grid optional path.  "},{"type":"prose","html":"1.3.2 / r/makinghiphop cousin: leave the sample <strong>raw</strong>, tap the Set to the record, write drums <em>to</em> the sample. Optional. If Auto-Warp already won and you like it, stay warped."},{"type":"prose","html":"Do not invent a BPM to make the tap look official."},{"type":"prose","html":"<strong>Check:</strong> You can say whether this sketch is WARP, CHOP, or RAW (1.3.6)."}]}],"minutes":8},{"id":"production-l4-1-10","title":"5.1.10 — MK4 pad performance of the flip","blocks":[{"type":"step","title":"5.1.10 — MK4 pad performance of the flip","blocks":[{"type":"prose","html":"<strong>Short description:</strong> MK4 pad performance of the flip.  "},{"type":"prose","html":"Drum mode. Play the re-ordered pattern live. Capture or record into the hook or verse slot. Clip mode still launches scenes."},{"type":"prose","html":"<strong>Check:</strong> The flipped pattern exists as a performed clip, not only a pencil staircase."}]}],"minutes":8},{"id":"production-l4-1-11","title":"5.1.11 — 32–64 bar sketch","blocks":[{"type":"step","title":"5.1.11 — 32–64 bar sketch","blocks":[{"type":"prose","html":"<strong>Short description:</strong> 32–64 bar sketch.  "},{"type":"prose","html":"Common-grid arithmetic example (not required): 4 intro + 16 verse + 8 hook + 16 verse + 8 hook + 8 outro = <strong>60</strong> bars. Or a shorter 32 (8+8+8+8). Listen file <code>LAB_hh_sketch.wav</code>."},{"type":"prose","html":"<strong>Check:</strong> Not an 8-bar loop exported four times in a row without scene changes."}]}],"minutes":8},{"id":"production-l4-1-12","title":"5.1.12 — Written bar counts vs the “common grid”","blocks":[{"type":"step","title":"5.1.12 — Written bar counts vs the “common grid”","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Written bar counts vs the “common grid”.  "},{"type":"prose","html":"Table: scene name | your bars | Cole/AudeoBox citation | match or <code>gap</code>."},{"type":"prose","html":"<strong>Section 5.1 checkpoint:</strong> You cited the 16/8 grid or you marked a gap. You did not legislate it."}]}],"minutes":8},{"id":"production-l4-2-1","title":"5.2.1 — Trap song shape vs boom-bap loop shape","blocks":[{"type":"step","title":"5.2.1 — Trap song shape vs boom-bap loop shape","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Trap song shape vs boom-bap loop shape.  "},{"type":"prose","html":"Beat Kitchen (0.9): trap (with dubstep) uses a <strong>pop-shaped</strong> drop form — intro–build–drop–breakdown–second build–second drop–outro — often <strong>3–5 minutes</strong>. The drop is a <strong>texture/energy</strong> shift, not “the band is back.”"},{"type":"prose","html":"Boom-bap (4.1) can live on a loop + hook. Trap scenes need a <strong>build</strong> and a <strong>drop</strong> even in a 32-bar sketch."},{"type":"prose","html":"<strong>Check:</strong> Your trap scene list contains a build and a drop, not only verse/hook."}]}],"minutes":8},{"id":"production-l4-2-2","title":"5.2.2 — Cited tempo band only (show both sources)","blocks":[{"type":"step","title":"5.2.2 — Cited tempo band only (show both sources)","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Cited tempo band only (show both sources).  "},{"type":"table","headers":["Source","Band"],"rows":[["<em>How To Make Trap</em> (EDMProd-family local PDF)","Most trap <strong>140–160</strong>; their worked example <strong>160</strong> for energetic / Trap Nation-adjacent"],["Beat Kitchen (L0 table)","<strong>130–170</strong> half-time"]],"caption":null},{"type":"prose","html":"Show both. Do not average to 150 and call it science. Pick a number <strong>inside a cited band</strong> or tap and refuse a genre claim."},{"type":"prose","html":"Half-time at 140 <em>feels</em> like 70. That is still one tempo (1.3.5)."},{"type":"prose","html":"<strong>Check:</strong> The tempo field is either inside a cited band or unlabeled."}]}],"minutes":8},{"id":"production-l4-2-3","title":"5.2.3 — Scene map: intro / verse / hook / drop","blocks":[{"type":"step","title":"5.2.3 — Scene map: intro / verse / hook / drop","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Scene map: intro / verse / hook / drop.  "},{"type":"prose","html":"Minimum rows: <code>Intro</code> · <code>Verse</code> · <code>Build</code> · <code>Drop</code> · <code>Hook</code> (hook may <em>be</em> the drop in vocal trap — write which). Optional: <code>Break</code> · <code>Drop_2</code>."},{"type":"prose","html":"If you cannot tell hook from drop, write one sentence: “hook = vocal chant; drop = 808 + hat density.”"},{"type":"prose","html":"<strong>Check:</strong> Every row has a job word, not <code>scene 3</code>."}]}],"minutes":8},{"id":"production-l4-2-4","title":"5.2.4 — Half-time as a form feeling","blocks":[{"type":"step","title":"5.2.4 — Half-time as a form feeling","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Half-time as a form feeling.  "},{"type":"prose","html":"Snare on <strong>3</strong> at a 140-ish grid makes the bar feel like two slow pulses. That feeling <em>is</em> the section identity of many trap drops. You do not change the Control Bar to 70 unless you mean it."},{"type":"prose","html":"Do not write a drum-programming thesis. Place a stock snare on 3 in the drop clip. Verse may use a busier backbeat. The contrast is form."},{"type":"prose","html":"<strong>Check:</strong> Drop snare is on 3. You did not call that “two tempos.”"}]}],"minutes":8},{"id":"production-l4-2-5","title":"5.2.5 — 808 notes on keys — tune to the song, do not design FM","blocks":[{"type":"step","title":"5.2.5 — 808 notes on keys — tune to the song, do not design FM","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Tune to the song, do not design FM.  "},{"type":"prose","html":"An 808 in this lab is a <strong>pitched bass role</strong>: Core Library / Drum Rack 808 or a Simpler bass hit played on the <strong>keys</strong>. Tune the notes to the chord clip. Slide between notes if the stock device allows — you are writing a bass <em>line</em>, not an FM patch."},{"type":"prose","html":"Operator stays closed."},{"type":"prose","html":"<strong>Check:</strong> 808 notes agree with the keys clip. No new synth architecture."}]}],"minutes":8},{"id":"production-l4-2-6","title":"5.2.6 — Hat density as section contrast (stock hats)","blocks":[{"type":"step","title":"5.2.6 — Hat density as section contrast (stock hats)","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Hat density as section contrast (stock hats).  "},{"type":"prose","html":"Verse: sparse closed hats. Drop: busier hat clip. <strong>Stock hats.</strong> 32nd-note programming, rolls, and humanize curves belong to the Drums course."},{"type":"prose","html":"Density is a §9.4 lever (more events, not louder)."},{"type":"prose","html":"<strong>Check:</strong> Two hat clips, different note counts, same sample."}]}],"minutes":8},{"id":"production-l4-2-7","title":"5.2.7 — Silence / riser as the build (form, not SD)","blocks":[{"type":"step","title":"5.2.7 — Silence / riser as the build (form, not SD)","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Silence / riser as the build (form, not SD).  "},{"type":"prose","html":"0.9.6: a <strong>build</strong> is a section type. A <strong>riser</strong> is one tool (a clip). Trap often uses <strong>silence</strong> (a bar of almost-nothing) plus a riser into the drop."},{"type":"prose","html":"Launch <code>Build</code>: subtract the 808, add a riser clip (Core Library FX). Do not design a wavetable sweep."},{"type":"prose","html":"<strong>Check:</strong> <code>Build</code> is defined by what you <strong>removed</strong>, plus one upward clip."}]}],"minutes":8},{"id":"production-l4-2-8","title":"5.2.8 — Second drop = one clip swapped","blocks":[{"type":"step","title":"5.2.8 — Second drop = one clip swapped","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Second drop = one clip swapped.  "},{"type":"prose","html":"<code>Drop_2</code> = <code>Drop</code> with one clip changed (a new 808 rhythm, a chopped vocal). Same form. EDMProd “use every stem” is a mistake (canon #11); one swap is enough."},{"type":"prose","html":"<strong>Check:</strong> Diff is one clip."}]}],"minutes":8},{"id":"production-l4-2-9","title":"5.2.9 — MK4: hook scene vs verse scene","blocks":[{"type":"step","title":"5.2.9 — MK4: hook scene vs verse scene","blocks":[{"type":"prose","html":"<strong>Short description:</strong> On the Launchkey MK4 61: hook scene vs verse scene.  "},{"type":"prose","html":"Clip mode: launch <code>Verse</code> then <code>Hook</code>/<code>Drop</code>. Feel half-time arrive. Keys still play 808s if you armed that track."},{"type":"prose","html":"<strong>Check:</strong> A listener could clap the difference without seeing the grid."}]}],"minutes":8},{"id":"production-l4-2-10","title":"5.2.10 — 32-bar sketch","blocks":[{"type":"step","title":"5.2.10 — 32-bar sketch","blocks":[{"type":"prose","html":"<strong>Short description:</strong> 32-bar sketch.  "},{"type":"prose","html":"Thirty-two bars is a <strong>lab</strong>, not a 3–5 minute Beat Kitchen single. Example: 8 intro + 8 verse + 8 build + 8 drop. Listen file <code>LAB_trap_sketch.wav</code>."},{"type":"prose","html":"<strong>Section 5.2 checkpoint:</strong> You used hat density and/or silence as form, not a new bass-design session."}]},{"type":"step","title":"Sources for Module 4 (author-facing)","blocks":[{"type":"list","items":["Cole Mize, rap song-structure materials (8-bar hook / 12–16 bar verse)  ","AudeoBox MPC-classic bar map (syllabus)  ","Melodigging boom-bap ~85–96  ","<em>Drum Breaks</em> legality; 1.4 / 1.6  ","Beat Kitchen trap form + tempo table (L0)  ","<em>How To Make Trap Music: 7 Steps</em> (140–160; example 160)"],"ordered":false}]}],"minutes":8}],"exercises":[]}]};
